actions.script:
            success = false

            try {
                ec.logger.info("Marble ERP AI 销售预测请求: ${organizationPartyId}, 预测${forecastPeriods}期")

                // 通过统一MCP服务获取Marble ERP AI配置
                def configResult = ec.service.sync().name("mcp.ai.config.get#ModuleAiConfig")
                    .parameter("module", "marble")
                    .parameter("configType", "text")
                    .call()

                if (!configResult.success || !configResult.config?.apiKey) {
                    ec.logger.warn("Marble ERP AI配置获取失败，使用演示模式")
                    def demoResult = generateDemoSalesForecast(organizationPartyId, periodType, forecastPeriods)
                    forecastData = demoResult.forecastData
                    insights = demoResult.insights
                    confidence = demoResult.confidence
                    recommendations = demoResult.recommendations
                    success = true
                    return
                }

                def aiConfig = configResult.config

                // 获取历史销售数据
                def historicalSalesData = getHistoricalSalesData(organizationPartyId, productStoreId, periodType)

                // 构建销售预测提示词
                def prompt = buildSalesForeccastPrompt(historicalSalesData, periodType, forecastPeriods, includeSeasonality)

                // 调用统一的MCP数据分析服务
                def mcpResult = ec.service.sync().name("mcp.ai.analyze#Data")
                    .parameter("dataset", historicalSalesData)
                    .parameter("analysisType", "forecast")
                    .parameter("module", "marble")
                    .parameter("timeframe", "${forecastPeriods}${periodType}")
                    .parameter("aiProvider", aiConfig.provider)
                    .parameter("prompt", prompt)
                    .call()

                if (mcpResult.success) {
                    def result = parseSalesForecastResponse(mcpResult.insights, mcpResult.predictions)
                    forecastData = result.forecastData
                    insights = result.insights
                    confidence = result.confidence
                    recommendations = result.recommendations
                    success = true
                    ec.logger.info("Marble ERP 销售预测成功: 预测${forecastData.size()}期数据")
                } else {
                    ec.logger.warn("AI销售预测失败，使用演示模式: ${mcpResult.error}")
                    def demoResult = generateDemoSalesForecast(organizationPartyId, periodType, forecastPeriods)
                    forecastData = demoResult.forecastData
                    insights = demoResult.insights
                    confidence = demoResult.confidence
                    recommendations = demoResult.recommendations
                    success = true
                }

            } catch (Exception e) {
                ec.logger.error("Marble ERP销售预测错误", e)
                success = false
                error = e.message
            }

            // 获取历史销售数据
            def getHistoricalSalesData(orgPartyId, storeId, periodType) {
                def salesData = []

                try {
                    // 查询订单数据，聚合按时间期间
                    def orderList = ec.entity.find("mantle.order.OrderHeaderAndPart")
                        .condition("vendorPartyId", orgPartyId)
                        .condition("statusId", "in", ["OrderCompleted", "OrderShipped"])
                        .orderBy("-placedDate")
                        .limit(100)
                        .disableAuthz()
                        .list()

                    // 简化处理：按月分组
                    def monthlyRevenue = [:]
                    orderList.each { order ->
                        if (order.placedDate && order.grandTotal) {
                            def month = order.placedDate.format("yyyy-MM")
                            monthlyRevenue[month] = (monthlyRevenue[month] ?: 0.0) + (order.grandTotal ?: 0.0)
                        }
                    }

                    // 转换为时间序列数据
                    monthlyRevenue.each { month, revenue ->
                        salesData.add([
                            period: month,
                            revenue: revenue,
                            orders: orderList.count { it.placedDate?.format("yyyy-MM") == month }
                        ])
                    }

                    return salesData.sort { it.period }
                } catch (Exception e) {
                    ec.logger.warn("获取历史销售数据失败，使用模拟数据", e)
                    // 返回模拟历史数据
                    def currentMonth = new Date()
                    (1..12).each { i ->
                        def date = new Date(currentMonth.time - (i * 30 * 24 * 60 * 60 * 1000L))
                        salesData.add([
                            period: date.format("yyyy-MM"),
                            revenue: 50000 + (Math.random() * 30000),
                            orders: 100 + (int)(Math.random() * 50)
                        ])
                    }
                    return salesData.reverse()
                }
            }

            // 构建销售预测提示词
            def buildSalesForeccastPrompt(historicalData, periodType, forecastPeriods, includeSeasonality) {
                def prompt = """作为Marble ERP销售分析专家，请基于以下历史销售数据预测未来${forecastPeriods}个${periodType}的销售表现：

历史数据：
${historicalData.collect { "${it.period}: 收入 ¥${it.revenue.round(2)}, 订单 ${it.orders}笔" }.join('\n')}

分析要求：
1. 销售趋势分析（增长/下降/稳定）
2. 周期性模式识别${includeSeasonality ? '（重点关注季节性因素）' : ''}
3. 预测未来${forecastPeriods}期的收入和订单量
4. 分析影响因素和业务洞察
5. 提供经营建议和优化策略

请用JSON格式返回结果：
{
  "forecastData": [
    {
      "period": "预测期间",
      "predictedRevenue": "预测收入",
      "predictedOrders": "预测订单量",
      "confidenceLevel": "置信度(0-1)"
    }
  ],
  "insights": {
    "trendAnalysis": "趋势分析",
    "seasonalPatterns": "季节性模式",
    "growthRate": "平均增长率",
    "riskFactors": "风险因素"
  },
  "recommendations": [
    "经营建议1",
    "经营建议2",
    "经营建议3"
  ],
  "overallConfidence": "整体预测置信度(0-1)"
}"""
                return prompt
            }

            // 解析销售预测响应
            def parseSalesForecastResponse(insights, predictions) {
                try {
                    def jsonPattern = /\{[\s\S]*\}/
                    def jsonMatcher = insights =~ jsonPattern

                    if (jsonMatcher) {
                        def jsonText = jsonMatcher[0]
                        def result = new groovy.json.JsonSlurper().parseText(jsonText)

                        return [
                            forecastData: result.forecastData ?: [],
                            insights: result.insights ?: [:],
                            confidence: result.overallConfidence ?: 0.75,
                            recommendations: result.recommendations ?: []
                        ]
                    }
                } catch (Exception e) {
                    ec.logger.error("销售预测响应解析错误", e)
                }

                return generateDemoSalesForecast(organizationPartyId, periodType, forecastPeriods)
            }

            // 演示模式销售预测
            def generateDemoSalesForecast(orgPartyId, periodType, forecastPeriods) {
                def currentRevenue = 80000.0
                def growthRate = 0.05 // 5% 月增长
                def seasonalFactors = [1.2, 0.8, 0.9, 1.1, 1.0, 0.95, 0.85, 0.9, 1.1, 1.15, 1.25, 1.3] // 季节性因子

                def forecastData = []
                def currentDate = new Date()

                (1..forecastPeriods).each { period ->
                    def futureDate = new Date(currentDate.time + (period * 30 * 24 * 60 * 60 * 1000L))
                    def seasonIndex = (futureDate.month) % 12
                    def seasonalFactor = seasonalFactors[seasonIndex]

                    def predictedRevenue = currentRevenue * Math.pow(1 + growthRate, period) * seasonalFactor
                    def predictedOrders = (predictedRevenue / 400).round()

                    forecastData.add([
                        period: futureDate.format("yyyy-MM"),
                        predictedRevenue: predictedRevenue.round(2),
                        predictedOrders: predictedOrders,
                        confidenceLevel: 0.8 - (period * 0.02) // 预测期越远置信度越低
                    ])
                }

                return [
                    forecastData: forecastData,
                    insights: [
                        trendAnalysis: "基于历史数据显示稳定增长趋势，预计年增长率为60%",
                        seasonalPatterns: "第四季度通常表现最佳，夏季相对较弱",
                        growthRate: growthRate,
                        riskFactors: ["市场竞争加剧", "原材料成本上涨", "经济环境不确定性"]
                    ],
                    confidence: 0.78,
                    recommendations: [
                        "加强第四季度营销投入，抓住旺季机遇",
                        "夏季推出促销活动，提升淡季销售",
                        "优化产品结构，提高平均客单价",
                        "建立客户忠诚度计划，提高复购率",
                        "关注成本控制，维持利润率稳定"
                    ]
                ]
            }

            success = false

            try {
                ec.logger.info("Marble ERP AI 库存优化请求: ${facilityId}, 优化类型: ${optimizationType}")

                // 通过统一MCP服务获取Marble ERP AI配置
                def configResult = ec.service.sync().name("mcp.ai.config.get#ModuleAiConfig")
                    .parameter("module", "marble")
                    .parameter("configType", "text")
                    .call()

                if (!configResult.success || !configResult.config?.apiKey) {
                    ec.logger.warn("Marble ERP AI配置获取失败，使用演示模式")
                    def demoResult = generateDemoInventoryOptimization(facilityId, optimizationType)
                    optimizationResults = demoResult.optimizationResults
                    totalSavings = demoResult.totalSavings
                    performanceMetrics = demoResult.performanceMetrics
                    actionItems = demoResult.actionItems
                    success = true
                    return
                }

                def aiConfig = configResult.config

                // 获取库存数据
                def inventoryData = getCurrentInventoryData(facilityId, productCategory)

                // 构建库存优化提示词
                def prompt = buildInventoryOptimizationPrompt(inventoryData, optimizationType, targetServiceLevel)

                // 调用统一的MCP分析服务
                def mcpResult = ec.service.sync().name("mcp.ai.optimize#Resources")
                    .parameter("resourceData", inventoryData)
                    .parameter("optimizationType", optimizationType)
                    .parameter("module", "marble")
                    .parameter("constraints", [serviceLevel: targetServiceLevel])
                    .parameter("aiProvider", aiConfig.provider)
                    .parameter("prompt", prompt)
                    .call()

                if (mcpResult.success) {
                    def result = parseInventoryOptimizationResponse(mcpResult.optimizationPlan, mcpResult.metrics)
                    optimizationResults = result.optimizationResults
                    totalSavings = result.totalSavings
                    performanceMetrics = result.performanceMetrics
                    actionItems = result.actionItems
                    success = true
                    ec.logger.info("Marble ERP 库存优化成功: 总节省¥${totalSavings}")
                } else {
                    ec.logger.warn("AI库存优化失败，使用演示模式: ${mcpResult.error}")
                    def demoResult = generateDemoInventoryOptimization(facilityId, optimizationType)
                    optimizationResults = demoResult.optimizationResults
                    totalSavings = demoResult.totalSavings
                    performanceMetrics = demoResult.performanceMetrics
                    actionItems = demoResult.actionItems
                    success = true
                }

            } catch (Exception e) {
                ec.logger.error("Marble ERP库存优化错误", e)
                success = false
                error = e.message
            }

            // 获取当前库存数据
            def getCurrentInventoryData(facilityId, productCategory) {
                def inventoryData = []

                try {
                    def assetFindBuilder = ec.entity.find("mantle.product.asset.Asset")
                        .condition("assetTypeEnumId", "AstTpInventory")

                    if (facilityId) assetFindBuilder.condition("facilityId", facilityId)
                    if (productCategory) {
                        // 通过产品分类过滤
                        assetFindBuilder.condition("productId", "in",
                            ec.entity.find("mantle.product.ProductCategoryMember")
                                .condition("productCategoryId", productCategory)
                                .getFieldValues("productId"))
                    }

                    def assets = assetFindBuilder.limit(50).disableAuthz().list()

                    assets.each { asset ->
                        def product = asset.product
                        if (product) {
                            inventoryData.add([
                                productId: asset.productId,
                                productName: product.productName ?: asset.productId,
                                currentStock: asset.quantityOnHandTotal ?: 0,
                                reservedStock: asset.quantityReserved ?: 0,
                                availableStock: asset.availableToPromiseTotal ?: 0,
                                unitCost: asset.acquireCostUomId ? (asset.acquireCost ?: 0) : 50.0,
                                leadTimeDays: product.daysTillShipment ?: 7
                            ])
                        }
                    }

                    return inventoryData
                } catch (Exception e) {
                    ec.logger.warn("获取库存数据失败，使用模拟数据", e)
                    // 返回模拟库存数据
                    def productNames = ["智能手机", "笔记本电脑", "平板电脑", "智能手表", "耳机"]
                    productNames.each { name ->
                        inventoryData.add([
                            productId: "DEMO_${name.hashCode()}",
                            productName: name,
                            currentStock: 50 + (int)(Math.random() * 200),
                            reservedStock: (int)(Math.random() * 20),
                            availableStock: 30 + (int)(Math.random() * 150),
                            unitCost: 100 + (Math.random() * 500),
                            leadTimeDays: 3 + (int)(Math.random() * 10)
                        ])
                    }
                    return inventoryData
                }
            }

            // 构建库存优化提示词
            def buildInventoryOptimizationPrompt(inventoryData, optimizationType, targetServiceLevel) {
                def prompt = """作为Marble ERP库存管理专家，请基于以下库存数据进行${optimizationType}导向的优化分析：

当前库存状况：
${inventoryData.collect { "产品: ${it.productName}, 当前库存: ${it.currentStock}, 可用库存: ${it.availableStock}, 单位成本: ¥${it.unitCost.round(2)}, 交期: ${it.leadTimeDays}天" }.join('\n')}

优化目标：
- 优化类型: ${optimizationType == 'cost' ? '成本最优' : optimizationType == 'service_level' ? '服务水平最优' : '周转率最优'}
- 目标服务水平: ${(targetServiceLevel * 100).round(1)}%
- 考虑因素: 库存成本、缺货成本、周转率、服务水平

请提供优化建议：
1. 每个产品的最优库存水平
2. 补货策略和时机
3. 库存成本节省分析
4. 关键绩效指标改善预期
5. 具体行动项目

请用JSON格式返回结果：
{
  "optimizationResults": [
    {
      "productId": "产品ID",
      "productName": "产品名称",
      "currentStock": "当前库存",
      "optimalStock": "最优库存",
      "recommendedAction": "建议行动",
      "costSaving": "成本节省",
      "urgency": "紧急程度"
    }
  ],
  "performanceMetrics": {
    "totalInventoryValue": "总库存价值",
    "turnoverImprovement": "周转率改善",
    "serviceLevel": "预期服务水平",
    "reorderPoints": "补货点设置"
  },
  "actionItems": [
    "行动项目1",
    "行动项目2"
  ],
  "estimatedSavings": "预计总节省金额"
}"""
                return prompt
            }

            // 解析库存优化响应
            def parseInventoryOptimizationResponse(optimizationPlan, metrics) {
                try {
                    def jsonPattern = /\{[\s\S]*\}/
                    def jsonMatcher = optimizationPlan =~ jsonPattern

                    if (jsonMatcher) {
                        def jsonText = jsonMatcher[0]
                        def result = new groovy.json.JsonSlurper().parseText(jsonText)

                        return [
                            optimizationResults: result.optimizationResults ?: [],
                            totalSavings: result.estimatedSavings ?: 0,
                            performanceMetrics: result.performanceMetrics ?: [:],
                            actionItems: result.actionItems ?: []
                        ]
                    }
                } catch (Exception e) {
                    ec.logger.error("库存优化响应解析错误", e)
                }

                return generateDemoInventoryOptimization(facilityId, optimizationType)
            }

            // 演示模式库存优化
            def generateDemoInventoryOptimization(facilityId, optimizationType) {
                def products = [
                    [productId: "PROD001", productName: "智能手机", currentStock: 120, optimalStock: 80],
                    [productId: "PROD002", productName: "笔记本电脑", currentStock: 50, optimalStock: 75],
                    [productId: "PROD003", productName: "平板电脑", currentStock: 200, optimalStock: 150],
                    [productId: "PROD004", productName: "智能手表", currentStock: 30, optimalStock: 60],
                    [productId: "PROD005", productName: "无线耳机", currentStock: 80, optimalStock: 90]
                ]

                def optimizationResults = []
                def totalSavings = 0.0

                products.each { product ->
                    def stockDiff = product.currentStock - product.optimalStock
                    def unitCost = 200 + (Math.random() * 300)
                    def costSaving = stockDiff > 0 ? stockDiff * unitCost * 0.2 : 0 // 库存持有成本20%

                    def action = ""
                    def urgency = "低"
                    if (stockDiff > 20) {
                        action = "减少库存，释放资金"
                        urgency = "高"
                    } else if (stockDiff < -10) {
                        action = "增加库存，避免缺货"
                        urgency = "中"
                    } else {
                        action = "维持当前水平"
                        urgency = "低"
                    }

                    optimizationResults.add([
                        productId: product.productId,
                        productName: product.productName,
                        currentStock: product.currentStock,
                        optimalStock: product.optimalStock,
                        recommendedAction: action,
                        costSaving: costSaving.round(2),
                        urgency: urgency
                    ])

                    totalSavings += costSaving
                }

                return [
                    optimizationResults: optimizationResults,
                    totalSavings: totalSavings.round(2),
                    performanceMetrics: [
                        totalInventoryValue: "¥${(products.sum { it.currentStock * 250 }).round()}",
                        turnoverImprovement: "提升15-25%",
                        serviceLevel: "${(targetServiceLevel * 100).round(1)}%",
                        reorderPoints: "根据需求预测自动调整"
                    ],
                    actionItems: [
                        "建立自动补货预警机制",
                        "优化供应商交期管理",
                        "实施ABC分类库存策略",
                        "建立安全库存动态调整规则",
                        "加强需求预测准确性"
                    ]
                ]
            }

            success = false

            try {
                ec.logger.info("Marble ERP AI 财务异常检测请求: ${organizationPartyId}, 时间范围: ${analysisTimeframe}")

                // 通过统一MCP服务获取Marble ERP AI配置
                def configResult = ec.service.sync().name("mcp.ai.config.get#ModuleAiConfig")
                    .parameter("module", "marble")
                    .parameter("configType", "text")
                    .call()

                if (!configResult.success || !configResult.config?.apiKey) {
                    ec.logger.warn("Marble ERP AI配置获取失败，使用演示模式")
                    def demoResult = generateDemoAnomalyDetection(organizationPartyId, analysisTimeframe)
                    anomalies = demoResult.anomalies
                    riskScore = demoResult.riskScore
                    recommendations = demoResult.recommendations
                    complianceStatus = demoResult.complianceStatus
                    success = true
                    return
                }

                def aiConfig = configResult.config

                // 获取财务数据
                def financialData = getFinancialAnalysisData(organizationPartyId, analysisTimeframe)

                // 构建异常检测提示词
                def prompt = buildAnomalyDetectionPrompt(financialData, anomalyTypes, sensitivity)

                // 调用统一的MCP风险分析服务
                def mcpResult = ec.service.sync().name("mcp.ai.analyze#Risk")
                    .parameter("riskData", financialData)
                    .parameter("riskTypes", anomalyTypes ?: "fraud,compliance,performance")
                    .parameter("module", "marble")
                    .parameter("sensitivity", sensitivity)
                    .parameter("aiProvider", aiConfig.provider)
                    .parameter("prompt", prompt)
                    .call()

                if (mcpResult.success) {
                    def result = parseAnomalyDetectionResponse(mcpResult.riskAssessment, mcpResult.alerts)
                    anomalies = result.anomalies
                    riskScore = result.riskScore
                    recommendations = result.recommendations
                    complianceStatus = result.complianceStatus
                    success = true
                    ec.logger.info("Marble ERP 财务异常检测成功: 风险评分${riskScore}")
                } else {
                    ec.logger.warn("AI异常检测失败，使用演示模式: ${mcpResult.error}")
                    def demoResult = generateDemoAnomalyDetection(organizationPartyId, analysisTimeframe)
                    anomalies = demoResult.anomalies
                    riskScore = demoResult.riskScore
                    recommendations = demoResult.recommendations
                    complianceStatus = demoResult.complianceStatus
                    success = true
                }

            } catch (Exception e) {
                ec.logger.error("Marble ERP财务异常检测错误", e)
                success = false
                error = e.message
            }

            // 获取财务分析数据
            def getFinancialAnalysisData(orgPartyId, timeframe) {
                def financialData = [:]

                try {
                    // 计算时间范围
                    def endDate = new Date()
                    def months = timeframe.contains("month") ?
                        (timeframe.contains("3") ? 3 : timeframe.contains("6") ? 6 : 1) : 12
                    def startDate = new Date(endDate.time - (months * 30 * 24 * 60 * 60 * 1000L))

                    // 获取发票数据
                    def invoices = ec.entity.find("mantle.account.invoice.Invoice")
                        .condition("fromPartyId", orgPartyId)
                        .condition("invoiceDate", ">", startDate)
                        .limit(200)
                        .disableAuthz()
                        .list()

                    // 获取付款数据
                    def payments = ec.entity.find("mantle.account.payment.Payment")
                        .condition("fromPartyId", orgPartyId)
                        .condition("effectiveDate", ">", startDate)
                        .limit(200)
                        .disableAuthz()
                        .list()

                    financialData.invoices = invoices.collect { [
                        invoiceId: it.invoiceId,
                        amount: it.invoiceTotal ?: 0,
                        date: it.invoiceDate,
                        status: it.statusId,
                        type: it.invoiceTypeEnumId
                    ] }

                    financialData.payments = payments.collect { [
                        paymentId: it.paymentId,
                        amount: it.amount ?: 0,
                        date: it.effectiveDate,
                        method: it.paymentMethodTypeEnumId
                    ] }

                    financialData.summary = [
                        totalInvoices: invoices.size(),
                        totalPayments: payments.size(),
                        invoiceAmount: invoices.sum { it.invoiceTotal ?: 0 } ?: 0,
                        paymentAmount: payments.sum { it.amount ?: 0 } ?: 0
                    ]

                    return financialData
                } catch (Exception e) {
                    ec.logger.warn("获取财务数据失败，使用模拟数据", e)
                    // 返回模拟财务数据
                    return [
                        invoices: [[invoiceId: "INV001", amount: 10000, date: new Date()]],
                        payments: [[paymentId: "PAY001", amount: 10000, date: new Date()]],
                        summary: [totalInvoices: 25, totalPayments: 23, invoiceAmount: 250000, paymentAmount: 240000]
                    ]
                }
            }

            // 构建异常检测提示词
            def buildAnomalyDetectionPrompt(financialData, anomalyTypes, sensitivity) {
                def prompt = """作为Marble ERP财务风控专家，请基于以下财务数据进行异常检测分析：

财务数据概况：
- 发票数量: ${financialData.summary.totalInvoices}笔
- 付款数量: ${financialData.summary.totalPayments}笔
- 发票总金额: ¥${financialData.summary.invoiceAmount}
- 付款总金额: ¥${financialData.summary.paymentAmount}

异常检测重点：
${anomalyTypes?.split(',')?.collect {
    switch(it.trim()) {
        case 'fraud': return '- 欺诈检测: 异常交易模式、重复付款、虚假发票'
        case 'compliance': return '- 合规检测: 政策违规、审批流程、税务合规'
        case 'performance': return '- 绩效异常: 收入波动、成本异常、利润率变化'
        case 'cash_flow': return '- 现金流异常: 收支不匹配、账期异常、流动性风险'
        default: return "- ${it}: 其他财务异常"
    }
}.join('\n') ?: '- 综合异常检测: 欺诈、合规、绩效、现金流等全方位检测'}

检测敏感度: ${sensitivity == 'high' ? '高敏感度（检测更多潜在问题）' : sensitivity == 'low' ? '低敏感度（仅检测明显异常）' : '中等敏感度（平衡检测效果）'}

请提供检测结果：
1. 识别的具体异常情况
2. 风险等级评估和评分
3. 合规状态分析
4. 处理建议和预防措施

请用JSON格式返回结果：
{
  "anomalies": [
    {
      "type": "异常类型",
      "description": "异常描述",
      "severity": "严重程度",
