  },
  "recommendations": [
    "建议1",
    "建议2",
    "建议3"
  ]
}"""
                return prompt
            }

            // 解析异常检测响应
            def parseAnomalyDetectionResponse(riskAssessment, alerts) {
                try {
                    def jsonPattern = /\{[\s\S]*\}/
                    def jsonMatcher = riskAssessment =~ jsonPattern

                    if (jsonMatcher) {
                        def jsonText = jsonMatcher[0]
                        def result = new groovy.json.JsonSlurper().parseText(jsonText)

                        return [
                            anomalies: result.anomalies ?: [],
                            riskScore: result.riskScore ?: 0.3,
                            recommendations: result.recommendations ?: [],
                            complianceStatus: result.complianceStatus ?: [:]
                        ]
                    }
                } catch (Exception e) {
                    ec.logger.error("异常检测响应解析错误", e)
                }

                return generateDemoAnomalyDetection(organizationPartyId, analysisTimeframe)
            }

