            success = false

            try {
                ec.logger.info("Marble ERP AI 人力资源分析请求: ${organizationPartyId}, 范围: ${analysisScope}")

                // 通过统一MCP服务获取Marble ERP AI配置
                def configResult = ec.service.sync().name("mcp.ai.config.get#ModuleAiConfig")
                    .parameter("module", "marble")
                    .parameter("configType", "text")
                    .call()

                if (!configResult.success || !configResult.config?.apiKey) {
                    ec.logger.warn("Marble ERP AI配置获取失败，使用演示模式")
                    def demoResult = generateDemoHRAnalysis(organizationPartyId, metricsType)
                    hrMetrics = demoResult.hrMetrics
                    insights = demoResult.insights
                    recommendations = demoResult.recommendations
                    actionPlan = demoResult.actionPlan
                    success = true
                    return
                }

                def aiConfig = configResult.config

                // 获取人力资源数据
                def hrData = getHRAnalysisData(organizationPartyId, departmentId)

                // 构建HR分析提示词
                def prompt = buildHRAnalysisPrompt(hrData, analysisScope, metricsType)

                // 调用统一的MCP分析服务
                def mcpResult = ec.service.sync().name("mcp.ai.analyze#Personnel")
                    .parameter("personnelData", hrData)
                    .parameter("analysisType", metricsType)
                    .parameter("module", "marble")
                    .parameter("scope", analysisScope)
                    .parameter("aiProvider", aiConfig.provider)
                    .parameter("prompt", prompt)
                    .call()

                if (mcpResult.success) {
                    def result = parseHRAnalysisResponse(mcpResult.analysis, mcpResult.insights)
                    hrMetrics = result.hrMetrics
                    insights = result.insights
                    recommendations = result.recommendations
                    actionPlan = result.actionPlan
                    success = true
                    ec.logger.info("Marble ERP 人力资源分析成功")
                } else {
                    ec.logger.warn("AI人力资源分析失败，使用演示模式: ${mcpResult.error}")
                    def demoResult = generateDemoHRAnalysis(organizationPartyId, metricsType)
                    hrMetrics = demoResult.hrMetrics
                    insights = demoResult.insights
                    recommendations = demoResult.recommendations
                    actionPlan = demoResult.actionPlan
                    success = true
                }

            } catch (Exception e) {
                ec.logger.error("Marble ERP人力资源分析错误", e)
                success = false
                error = e.message
            }

            // 获取人力资源分析数据
            def getHRAnalysisData(orgPartyId, deptId) {
                def hrData = [:]

                try {
                    // 获取员工数据
                    def employees = ec.entity.find("mantle.party.PartyRole")
                        .condition("roleTypeId", "Employee")
                        .limit(100)
                        .disableAuthz()
                        .list()

                    hrData.totalEmployees = employees.size()
                    hrData.departments = ["技术部", "销售部", "市场部", "财务部", "人事部"]
                    hrData.positions = ["经理", "主管", "专员", "助理", "实习生"]

                    // 模拟员工分布数据
                    hrData.employeesByDepartment = [
                        "技术部": 25,
                        "销售部": 15,
                        "市场部": 8,
                        "财务部": 5,
                        "人事部": 4
                    ]

                    hrData.employeesByPosition = [
                        "经理": 5,
                        "主管": 12,
                        "专员": 30,
                        "助理": 8,
                        "实习生": 2
                    ]

                    return hrData
                } catch (Exception e) {
                    ec.logger.warn("获取人力资源数据失败，使用模拟数据", e)
                    return [
                        totalEmployees: 57,
                        departments: ["技术部", "销售部", "市场部"],
                        positions: ["经理", "专员", "助理"],
                        employeesByDepartment: ["技术部": 25, "销售部": 20, "市场部": 12],
                        employeesByPosition: ["经理": 5, "专员": 40, "助理": 12]
                    ]
                }
            }

            // 构建HR分析提示词
            def buildHRAnalysisPrompt(hrData, analysisScope, metricsType) {
                def prompt = """作为Marble ERP人力资源分析专家，请基于以下数据进行${metricsType}导向的分析：

组织人力资源概况：
- 总员工数: ${hrData.totalEmployees}人
- 部门分布: ${hrData.employeesByDepartment}
- 职位分布: ${hrData.employeesByPosition}
- 分析范围: ${analysisScope}

分析重点：
${metricsType == 'performance' ? '绩效分析：员工表现、生产力、目标达成率' :
  metricsType == 'retention' ? '留存分析：离职率、员工满意度、职业发展' :
  metricsType == 'satisfaction' ? '满意度分析：工作环境、薪酬福利、团队合作' :
  '综合分析：绩效、留存、满意度全面评估'}

请提供分析结果：
1. 关键人力资源指标分析
2. 深度洞察和发现
3. 改进建议和策略
4. 具体行动计划

请用JSON格式返回结果：
{
  "hrMetrics": {
    "performanceScore": "绩效评分",
    "retentionRate": "员工留存率",
    "satisfactionIndex": "满意度指数",
    "productivityIndex": "生产力指数",
    "engagementLevel": "员工敬业度",
    "departmentRankings": "部门排名"
  },
  "insights": [
    {
      "category": "洞察类别",
      "finding": "发现内容",
      "impact": "影响程度",
      "priority": "优先级"
    }
  ],
  "recommendations": [
    "建议1",
    "建议2",
    "建议3"
  ],
  "actionPlan": {
    "shortTerm": "短期行动(1-3个月)",
    "mediumTerm": "中期行动(3-6个月)",
    "longTerm": "长期行动(6-12个月)"
  }
}"""
                return prompt
            }

            // 解析HR分析响应
            def parseHRAnalysisResponse(analysis, insights) {
                try {
                    def jsonPattern = /\{[\s\S]*\}/
                    def jsonMatcher = analysis =~ jsonPattern

                    if (jsonMatcher) {
                        def jsonText = jsonMatcher[0]
                        def result = new groovy.json.JsonSlurper().parseText(jsonText)

                        return [
                            hrMetrics: result.hrMetrics ?: [:],
                            insights: result.insights ?: [],
                            recommendations: result.recommendations ?: [],
                            actionPlan: result.actionPlan ?: [:]
                        ]
                    }
                } catch (Exception e) {
                    ec.logger.error("HR分析响应解析错误", e)
                }

                return generateDemoHRAnalysis(organizationPartyId, metricsType)
            }

